var mode = false; // false = Anatomy, true = Equation parameters

// Setup Plot Frame
var frame = setPlotFrame({ xDomain: [-8.5, 8.5], yDomain: [-8.5, 8.5], margin: 25 });

// ── SVG Markers for axes and dimension lines ─────────────────────────────
function createArrowMarker(color, isStart) {
    return frame.draw.marker(10, 10, function(add) {
        if (isStart) add.path('M10,0 L0,5 L10,10 Z').fill(color);
        else add.path('M0,0 L10,5 L0,10 Z').fill(color);
    }).ref(isStart ? 0 : 10, 5).orient('auto');
}
var axisStart = createArrowMarker('#333', true);
var axisEnd = createArrowMarker('#333', false);
var dimStartBlue = createArrowMarker('#006699', true);
var dimEndBlue = createArrowMarker('#006699', false);
var dimStartBlack = createArrowMarker('#000000', true);
var dimEndBlack = createArrowMarker('#000000', false);
var dimStartGreen = createArrowMarker('#00aa55', true);
var dimEndGreen = createArrowMarker('#00aa55', false);

// ── SVG Groups ─────────────────────────────────────────────────────────
var gGrid = frame.draw.group();
var gAxes = frame.draw.group();
var gDashed = frame.draw.group();
var gEllipse = frame.draw.group();
var gParams = frame.draw.group();
var gDots = frame.draw.group();
var gAnatomy = frame.draw.group();

// ── Elements ───────────────────────────────────────────────────────────
// Background Grid
var gridLines = [];
for (let i = 0; i <= 16; i++) {
    gridLines.push({
        h: gGrid.line().stroke({color: '#f2f2f2', width: 1}),
        v: gGrid.line().stroke({color: '#f2f2f2', width: 1})
