var txtX = gAxes.text("x").font({size: 16, style: 'italic'});
var txtY = gAxes.text("y").font({size: 16, style: 'italic'});

// Ellipse & Dashed Lines
var ellipsePath = gEllipse.ellipse().fill('rgba(0,102,153,0.04)').stroke({color: '#006699', width: 2.5});
