var txtMinAxis = gAnatomy.text("Minor Axis").font({size: 14.5}).fill('#cc0000');

// ── Helpers ────────────────────────────────────────────────────────────
// Places text reliably avoiding overlapping lines using an SVG paint-order halo
function placeText(t, x, y, anchor, baseline) {
    t.attr({
        x: x, y: y, 
        'text-anchor': anchor, 
        'dominant-baseline': baseline || 'middle',
        'paint-order': 'stroke', stroke: '#fff', 'stroke-width': 4.5, 'stroke-linejoin': 'round'
    });
}

// Draws a dimension line (shifted in screen coordinates) with tracking lines
function drawDimLabel(name, x1, y1, x2, y2, shiftX, shiftY, color, mStart, mEnd) {
    let px1 = plotX(x1), py1 = plotY(y1);
    let px2 = plotX(x2), py2 = plotY(y2);
    let bx1 = px1 + shiftX, by1 = py1 + shiftY;
    let bx2 = px2 + shiftX, by2 = py2 + shiftY;

    // Dimension line with arrows
    gParams.line(bx1, by1, bx2, by2).stroke({color: color, width: 1.5}).marker('start', mStart).marker('end', mEnd);
    // Guide extensions
    gParams.line(px1, py1, bx1, by1).stroke({color: color, width: 1, dasharray: '3,3', opacity: 0.5});
    gParams.line(px2, py2, bx2, by2).stroke({color: color, width: 1, dasharray: '3,3', opacity: 0.5});

    // Position text label
    let tx = (bx1 + bx2)/2 + (shiftX !== 0 ? Math.sign(shiftX) * 16 : 0);
    let ty = (by1 + by2)/2 + (shiftY !== 0 ? Math.sign(shiftY) * 16 : 0);

    let t = gParams.text(name).font({size: 20, family: 'serif', style: 'italic'}).fill(color);
    placeText(t, tx, ty, 'middle', 'middle');
}

// ── Core Update Logic ──────────────────────────────────────────────────
function render() {
    let px0 = plotX(0), py0 = plotY(0);

    // Update Grid
    for (let i = -8; i <= 8; i++) {
        let idx = i + 8;
        gridLines[idx].h.plot(plotX(-8.5), plotY(i), plotX(8.5), plotY(i));
        gridLines[idx].v.plot(plotX(i), plotY(-8.5), plotX(i), plotY(8.5));
