    vDash.plot(px0, plotY(-b), px0, plotY(b));

    // Geometry calculations
    let isHorizontalMajor = a >= b;
    let c = Math.sqrt(Math.abs(a*a - b*b));

    let v1x = isHorizontalMajor ? a : 0, v1y = isHorizontalMajor ? 0 : b;
    let v2x = isHorizontalMajor ? -a : 0, v2y = isHorizontalMajor ? 0 : -b;
    let cv1x = isHorizontalMajor ? 0 : a, cv1y = isHorizontalMajor ? b : 0;
    let cv2x = isHorizontalMajor ? 0 : -a, cv2y = isHorizontalMajor ? -b : 0;
    let f1x = isHorizontalMajor ? c : 0, f1y = isHorizontalMajor ? 0 : c;
    let f2x = isHorizontalMajor ? -c : 0, f2y = isHorizontalMajor ? 0 : -c;

    // Update Control Points
    centerDot.center(px0, py0);
    v1Dot.center(plotX(v1x), plotY(v1y));
    v2Dot.center(plotX(v2x), plotY(v2y));
    cv1Dot.center(plotX(cv1x), plotY(cv1y));
    cv2Dot.center(plotX(cv2x), plotY(cv2y));
    f1Dot.center(plotX(f1x), plotY(f1y));
    f2Dot.center(plotX(f2x), plotY(f2y));

    // Tooltips
    centerDot.off('mousemove').on('mousemove', e => showTooltip('Center (0, 0)', e)).on('mouseleave', hideTooltip);
    v1Dot.off('mousemove').on('mousemove', e => showTooltip(`Vertex (${v1x.toFixed(1)}, ${v1y.toFixed(1)})`, e)).on('mouseleave', hideTooltip);
    v2Dot.off('mousemove').on('mousemove', e => showTooltip(`Vertex (${v2x.toFixed(1)}, ${v2y.toFixed(1)})`, e)).on('mouseleave', hideTooltip);
    cv1Dot.off('mousemove').on('mousemove', e => showTooltip(`Co-vertex (${cv1x.toFixed(1)}, ${cv1y.toFixed(1)})`, e)).on('mouseleave', hideTooltip);
    cv2Dot.off('mousemove').on('mousemove', e => showTooltip(`Co-vertex (${cv2x.toFixed(1)}, ${cv2y.toFixed(1)})`, e)).on('mouseleave', hideTooltip);
    f1Dot.off('mousemove').on('mousemove', e => showTooltip(`Focus (${f1x.toFixed(2)}, ${f1y.toFixed(2)})`, e)).on('mouseleave', hideTooltip);
    f2Dot.off('mousemove').on('mousemove', e => showTooltip(`Focus (${f2x.toFixed(2)}, ${f2y.toFixed(2)})`, e)).on('mouseleave', hideTooltip);

    if (!mode) {
        gAnatomy.show();
        gParams.hide();
        placeText(txtCenter, px0 - 8, py0 + 12, 'end', 'hanging');

