            placeText(txtV2, plotX(-a) - 12, py0, 'end');
            placeText(txtCV1, px0 + 12, plotY(b) - 10, 'start', 'bottom');
            placeText(txtCV2, px0 + 12, plotY(-b) + 10, 'start', 'hanging');
            placeText(txtF1, plotX(c), py0 + 16, 'middle', 'hanging');
            placeText(txtF2, plotX(-c), py0 + 16, 'middle', 'hanging');
            placeText(txtMajAxis, plotX(a/2), py0 - 12, 'middle', 'bottom');
            placeText(txtMinAxis, px0 - 12, plotY(b/2), 'end', 'middle');
        } else {
            placeText(txtV1, px0 + 12, plotY(b) - 10, 'start', 'bottom');
            placeText(txtV2, px0 + 12, plotY(-b) + 10, 'start', 'hanging');
            placeText(txtCV1, plotX(a) + 12, py0, 'start');
            placeText(txtCV2, plotX(-a) - 12, py0, 'end');
            placeText(txtF1, px0 - 12, plotY(c), 'end', 'middle');
            placeText(txtF2, px0 - 12, plotY(-c), 'end', 'middle');
            placeText(txtMajAxis, px0 - 12, plotY(b/2), 'end', 'middle');
            placeText(txtMinAxis, plotX(a/2), py0 - 12, 'middle', 'bottom');
        }
    } else {
        gAnatomy.hide();
        gParams.show();
        gParams.clear(); // Rebuild params text each frame due to orientation shifts

        drawDimLabel('a', 0, 0, a, 0, 0, 50, '#006699', dimStartBlue, dimEndBlue);
        drawDimLabel('b', 0, 0, 0, b, -50, 0, '#000000', dimStartBlack, dimEndBlack);

        // Hide focal parameter dimension if it reduces exactly to a circle
        if (c >= 0.1) {
            if (isHorizontalMajor) {
                drawDimLabel('c', 0, 0, c, 0, 0, -45, '#00aa55', dimStartGreen, dimEndGreen);
            } else {
                drawDimLabel('c', 0, 0, 0, c, 45, 0, '#00aa55', dimStartGreen, dimEndGreen);
            }
        }
    }
}

